head.script:
scwin.init = function() {
    console.log('start...');
    dataList1.setJSON(jsonData);
};
scwin.gridView1_onviewchange = function(info) {
    console.log('onviewChange')
    if (info.newSelectedIndex < 1) {
        console.log('add');
        var tmpData = {
            col1: info.newValue,
            col2: info.newValue
        };
        select_data.setRowJSON(0, tmpData, false);
    }
};
scwin.gridView1_ongroupby = function() {
    return false;
}
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[2].checked == false;
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getObjById('gridView1_groupbyFilterBox_apply').checked == false;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 'name1'항목의 필터(역삼각형)를 클릭한다.
    //1. After running the sample, click the filter (inverted triangle) in the 'name1' item.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column3_filter').click()");
    //Verify step 1. filterList가 보여진다.
    //1. The filterList is shown.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_customFilter_scrollView').is(':visible')", "true");
    //Test step 2. '전체선택'을 체크하여 체크해제하고 마우스를 다른곳 클릭한다.(blur)
    //2. Check 'Select All' to uncheck it and click the mouse somewhere else (blur)
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[2].click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 2. '전체선택'이 체크해제되고 하단의 groupbyFilterBox의 체크박스가 체크되어 보여진다.
    //2. The 'Select All' checkbox is unchecked and the checkbox of the groupbyFilterBox at the bottom is checked.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column3_filter').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_groupbyFilterBox_apply').checked", "true");
    //Test step 3. 다시 'name1'항목의 필터(역삼각형)를 클릭하고 '전체선택'을 체크하고 마우스를 다른곳 클릭한다.(blur)참고사항) IE7에서는 css문제로 groupbyFilterBox의 체크박스가 보이지않음(테스트제외)
    //3. Click the filter (inverted triangle) in the 'name1' item again, check 'Select all' and click the mouse somewhere else. (Blur) Note IE7 does not show checkbox of groupbyFilterBox due to css problem except)
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column3_filter').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[2].click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 3. 하단의 groupbyFilterBox의 체크박스가 체크가 해제되어 보여진다.(groupbyFilterBox의 filterList는 유지되는것이 정상임)(이전에는 groupbyFilterBox의 체크박스가 체크되어 보여짐)
    //3. The checkbox of the groupbyFilterBox at the bottom is unchecked (the filter list of the groupbyFilterBox should be maintained) (Previously, the checkbox of groupbyFilterBox is checked)
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
